package com.algoprep.patterns.spring;
import static org.junit.jupiter.api.Assertions.*; import java.util.concurrent.atomic.AtomicLong; import org.junit.jupiter.api.Test;
class CircuitBreakerTest { @Test void opensThenRecoversAfterSuccessfulProbe(){AtomicLong now=new AtomicLong(100);CircuitBreaker breaker=new CircuitBreaker(2,50,now::get);breaker.recordFailure();assertEquals(CircuitBreaker.State.CLOSED,breaker.getState());breaker.recordFailure();assertFalse(breaker.allowRequest());now.addAndGet(50);assertTrue(breaker.allowRequest());assertEquals(CircuitBreaker.State.HALF_OPEN,breaker.getState());breaker.recordSuccess();assertEquals(CircuitBreaker.State.CLOSED,breaker.getState());} @Test void failedProbeReopensCircuit(){AtomicLong now=new AtomicLong();CircuitBreaker breaker=new CircuitBreaker(1,10,now::get);breaker.recordFailure();now.set(10);assertTrue(breaker.allowRequest());breaker.recordFailure();assertFalse(breaker.allowRequest());} }
